{
 "contract_type": "lease",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Lakeside Commons REIT, Inc."],
   "quote": "by and between Northwind Labs, Inc. (\"Tenant\") and Lakeside Commons REIT, Inc. (\"Landlord\")"
  },
  "counterparty": {
   "value": "Lakeside Commons REIT, Inc.",
   "quote": "Lakeside Commons REIT, Inc. (\"Landlord\")"
  },
  "effective_date": {
   "value": "2025-05-16",
   "quote": "made and entered into as of the 16th day of May, 2025 (the \"Effective Date\")"
  },
  "term_months": {
   "value": 24,
   "quote": "shall continue in effect for a period of 2 years"
  },
  "auto_renewal": {
   "value": false,
   "quote": "Tenant shall have one (1) option to renew the lease of the Premises for one additional period of five years."
  },
  "renewal_notice_days": {
   "value": null,
   "quote": null
  },
  "governing_law": {
   "value": "Florida",
   "quote": "shall be governed by the laws of the State of Florida"
  },
  "liability_cap": {
   "value": null,
   "quote": null
  },
  "payment_terms_days": {
   "value": null,
   "quote": null
  },
  "contract_value": {
   "value": 480000,
   "quote": "Tenant shall pay to Landlord annual base rent in the amount of USD 480,000."
  },
  "termination_for_convenience": {
   "value": null,
   "quote": null
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Rebecca Stone",
   "email": "rebecca.stone@lakeside.example",
   "title": "Asset Manager",
   "party": "Lakeside Commons REIT, Inc."
  }
 ],
 "risks": [
  {
   "id": "no_liability_cap",
   "severity": "medium",
   "message": "The lease has no limitation of liability clause, so Northwind's exposure to the Landlord is uncapped.",
   "quote": "EXCEPT AS EXPRESSLY SET OUT IN THIS AGREEMENT, NEITHER PARTY MAKES ANY OTHER WARRANTY, EXPRESS OR IMPLIED, INCLUDING ANY WARRANTY OF MERCHANTABILITY OR FITNESS FOR A PARTICULAR PURPOSE."
  },
  {
   "id": "no_termination_rights",
   "severity": "high",
   "message": "The lease contains no termination provisions, so Northwind appears locked into USD 480,000 per year for the full term with no early exit right.",
   "quote": "This Agreement shall commence on the Effective Date and shall continue in effect for a period of 2 years."
  },
  {
   "id": "renewal_terms_undefined",
   "severity": "medium",
   "message": "The renewal option sets no notice deadline and no renewal rent, so the five-year renewal could be disputed or lapse, and the rent for it is undefined.",
   "quote": "Tenant may exercise such option by giving written notice to Landlord."
  },
  {
   "id": "term_expiring_soon",
   "severity": "medium",
   "message": "The 2-year initial term runs from 2025-05-16 and ends around 2027-05-16. Because no notice period is stated, Northwind should decide on the renewal option well in advance.",
   "quote": "Tenant shall have one (1) option to renew the lease of the Premises for one additional period of five years."
  },
  {
   "id": "no_payment_terms_or_remedies",
   "severity": "low",
   "message": "Rent is payable in monthly installments, but the lease has no due date, late-payment or default provisions, which creates ambiguity.",
   "quote": "The annual base rent shall be payable in equal monthly installments."
  },
  {
   "id": "assignment_merger_exception",
   "severity": "low",
   "message": "Either party may assign to a successor in a merger or asset sale without consent, so Northwind could end up with a different landlord without having a say.",
   "quote": "Section 6.1 shall not apply to an assignment to a successor in a merger or in a sale of substantially all of the assets of the assigning Party."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a commercial lease under which Northwind Labs, Inc. rents office space at 400 Harbor Street, Suite 12 from Lakeside Commons REIT, Inc. for 2 years from 2025-05-16 at USD 480,000 per year, with one tenant option to renew for five years. The lease is governed by Florida law and has no liability cap, termination right or payment-deadline terms."
}
